INSERT INTO questions (topic, subject, category, question_en, question_ta, option_a_en, option_a_ta, option_b_en, option_b_ta, option_c_en, option_c_ta, option_d_en, option_d_ta, correct_answer, explanation_en, explanation_ta, tnpsc_tip_en, tnpsc_tip_ta, difficulty) VALUES ('Fundamental Rights', 'Polity', 'Polity', 'Which Article of the Indian Constitution abolishes untouchability and forbids its practice in any form?', 'இந்திய அரசியலமைப்பின் எந்த சட்டப்பிரிவு தீண்டாமையை ஒழிக்கிறது மற்றும் எந்த வடிவிலும் அதன் நடைமுறையை தடை செய்கிறது?', 'Article 14', 'சட்டப்பிரிவு 14', 'Article 15', 'சட்டப்பிரிவு 15', 'Article 17', 'சட்டப்பிரிவு 17', 'Article 19', 'சட்டப்பிரிவு 19', 'C', NULL, NULL, NULL, NULL, 'MEDIUM');
INSERT INTO questions (topic, subject, category, question_en, question_ta, option_a_en, option_a_ta, option_b_en, option_b_ta, option_c_en, option_c_ta, option_d_en, option_d_ta, correct_answer, explanation_en, explanation_ta, tnpsc_tip_en, tnpsc_tip_ta, difficulty) VALUES ('Fundamental Rights', 'Polity', 'Polity', 'The Right to Education (Article 21A) was inserted into the Constitution by which amendment?', 'கல்வி உரிமை (சட்டப்பிரிவு 21A) எந்த திருத்தத்தின் மூலம் அரசியலமைப்பில் சேர்க்கப்பட்டது?', '86th Amendment Act, 2002', '86வது திருத்தச் சட்டம், 2002', '93rd Amendment Act, 2005', '93வது திருத்தச் சட்டம், 2005', '44th Amendment Act, 1978', '44வது திருத்தச் சட்டம், 1978', '73rd Amendment Act, 1992', '73வது திருத்தச் சட்டம், 1992', 'A', NULL, NULL, NULL, NULL, 'MEDIUM');
INSERT INTO questions (topic, subject, category, question_en, question_ta, option_a_en, option_a_ta, option_b_en, option_b_ta, option_c_en, option_c_ta, option_d_en, option_d_ta, correct_answer, explanation_en, explanation_ta, tnpsc_tip_en, tnpsc_tip_ta, difficulty) VALUES ('Fundamental Rights', 'Polity', 'Polity', 'Consider the following statements: 1. Article 19 guarantees six freedoms to citizens of India. 2. Article 19 freedoms are available to both citizens and non-citizens. Which of the statements given above is/are correct?', 'பின்வரும் கூற்றுகளை கவனியுங்கள்: 1. சட்டப்பிரிவு 19 இந்திய குடிமக்களுக்கு ஆறு சுதந்திரங்களை உத்தரவாதம் செய்கிறது. 2. சட்டப்பிரிவு 19 சுதந்திரங்கள் குடிமக்கள் மற்றும் குடிமக்கள் அல்லாதவர்கள் இருவருக்கும் கிடைக்கும். மேலே கொடுக்கப்பட்ட கூற்றுகளில் எது/எவை சரியானது?', '1 only', '1 மட்டும்', '2 only', '2 மட்டும்', 'Both 1 and 2', '1 மற்றும் 2 இரண்டும்', 'Neither 1 nor 2', '1 மற்றும் 2 இரண்டுமில்லை', 'A', NULL, NULL, NULL, NULL, 'MEDIUM');
INSERT INTO questions (topic, subject, category, question_en, question_ta, option_a_en, option_a_ta, option_b_en, option_b_ta, option_c_en, option_c_ta, option_d_en, option_d_ta, correct_answer, explanation_en, explanation_ta, tnpsc_tip_en, tnpsc_tip_ta, difficulty) VALUES ('Fundamental Rights', 'Polity', 'Polity', 'Which Fundamental Right is described as the ''heart and soul'' of the Indian Constitution by Dr. B.R. Ambedkar?', 'எந்த அடிப்படை உரிமை டாக்டர் பி.ஆர். அம்பேத்கரால் இந்திய அரசியலமைப்பின் ''இதயம் மற்றும் ஆன்மா'' என்று விவரிக்கப்படுகிறது?', 'Right to Equality', 'சமத்துவ உரிமை', 'Right to Freedom', 'சுதந்திர உரிமை', 'Right to Constitutional Remedies', 'அரசியலமைப்பு தீர்வு உரிமை', 'Right against Exploitation', 'சுரண்டலுக்கு எதிரான உரிமை', 'C', NULL, NULL, NULL, NULL, 'MEDIUM');
INSERT INTO questions (topic, subject, category, question_en, question_ta, option_a_en, option_a_ta, option_b_en, option_b_ta, option_c_en, option_c_ta, option_d_en, option_d_ta, correct_answer, explanation_en, explanation_ta, tnpsc_tip_en, tnpsc_tip_ta, difficulty) VALUES ('Fundamental Rights', 'Polity', 'Polity', 'Article 32 of the Constitution gives the Supreme Court the power to issue writs. Which of the following writs is issued to release a person from illegal detention?', 'அரசியலமைப்பின் சட்டப்பிரிவு 32 உச்சநீதிமன்றத்திற்கு ரிட் வழங்கும் அதிகாரத்தை கொடுக்கிறது. பின்வரும் ரிட்களில் எது சட்டவிரோத தடுப்புக்காவலிலிருந்து ஒருவரை விடுவிக்க வழங்கப்படுகிறது?', 'Mandamus', 'மேன்டமஸ்', 'Certiorari', 'சர்ட்டியோரீ', 'Habeas Corpus', 'ஹேபியஸ் கார்பஸ்', 'Quo Warranto', 'குவோ வாரன்டோ', 'C', NULL, NULL, NULL, NULL, 'MEDIUM');
INSERT INTO questions (topic, subject, category, question_en, question_ta, option_a_en, option_a_ta, option_b_en, option_b_ta, option_c_en, option_c_ta, option_d_en, option_d_ta, correct_answer, explanation_en, explanation_ta, tnpsc_tip_en, tnpsc_tip_ta, difficulty) VALUES ('Fundamental Rights', 'Polity', 'Polity', 'Which Article of the Indian Constitution prohibits traffic in human beings and forced labour?', 'இந்திய அரசியலமைப்பின் எந்த சட்டப்பிரிவு மனித கடத்தல் மற்றும் கட்டாய தொழிலை தடைசெய்கிறது?', 'Article 21', 'சட்டப்பிரிவு 21', 'Article 23', 'சட்டப்பிரிவு 23', 'Article 24', 'சட்டப்பிரிவு 24', 'Article 25', 'சட்டப்பிரிவு 25', 'B', NULL, NULL, NULL, NULL, 'MEDIUM');
INSERT INTO questions (topic, subject, category, question_en, question_ta, option_a_en, option_a_ta, option_b_en, option_b_ta, option_c_en, option_c_ta, option_d_en, option_d_ta, correct_answer, explanation_en, explanation_ta, tnpsc_tip_en, tnpsc_tip_ta, difficulty) VALUES ('Fundamental Rights', 'Polity', 'Polity', 'Assertion (A): Fundamental Rights in India are not absolute. Reason (R): Reasonable restrictions can be imposed on Fundamental Rights in the interest of public order, morality, and national security. Choose the correct option:', 'கூற்று (A): இந்தியாவில் அடிப்படை உரிமைகள் முழுமையானவை அல்ல. காரணம் (R): பொது ஒழுங்கு, ஒழுக்கம் மற்றும் தேசிய பாதுகாப்பின் நலனில் அடிப்படை உரிமைகள் மீது நியாயமான கட்டுப்பாடுகள் விதிக்கப்படலாம். சரியான விருப்பத்தை தேர்ந்தெடுங்கள்:', 'A is correct and R is the correct explanation of A', 'A சரியானது மற்றும் R என்பது A இன் சரியான விளக்கம்', 'A is correct but R is not the correct explanation of A', 'A சரியானது ஆனால் R என்பது A இன் சரியான விளக்கம் இல்லை', 'A is correct but R is incorrect', 'A சரியானது ஆனால் R தவறானது', 'A is incorrect', 'A தவறானது', 'A', NULL, NULL, NULL, NULL, 'MEDIUM');
INSERT INTO questions (topic, subject, category, question_en, question_ta, option_a_en, option_a_ta, option_b_en, option_b_ta, option_c_en, option_c_ta, option_d_en, option_d_ta, correct_answer, explanation_en, explanation_ta, tnpsc_tip_en, tnpsc_tip_ta, difficulty) VALUES ('Fundamental Rights', 'Polity', 'Polity', 'Match the following Articles with their provisions: Article 14 — (i) Right against exploitation Article 19 — (ii) Right to equality Article 23 — (iii) Protection of life and personal liberty Article 21 — (iv) Right to freedom of speech Choose the correct matching:', 'பின்வரும் சட்டப்பிரிவுகளை அவற்றின் விதிகளுடன் பொருத்துக: சட்டப்பிரிவு 14 — (i) சுரண்டலுக்கு எதிரான உரிமை சட்டப்பிரிவு 19 — (ii) சமத்துவ உரிமை சட்டப்பிரிவு 23 — (iii) உயிர் மற்றும் தனி சுதந்திர பாதுகாப்பு சட்டப்பிரிவு 21 — (iv) பேச்சு சுதந்திரம் சரியான பொருத்தத்தை தேர்ந்தெடுங்கள்:', '14-(ii), 19-(iv), 23-(i), 21-(iii)', '14-(ii), 19-(iv), 23-(i), 21-(iii)', '14-(i), 19-(ii), 23-(iii), 21-(iv)', '14-(i), 19-(ii), 23-(iii), 21-(iv)', '14-(iii), 19-(i), 23-(iv), 21-(ii)', '14-(iii), 19-(i), 23-(iv), 21-(ii)', '14-(iv), 19-(iii), 23-(ii), 21-(i)', '14-(iv), 19-(iii), 23-(ii), 21-(i)', 'A', NULL, NULL, NULL, NULL, 'MEDIUM');
INSERT INTO questions (topic, subject, category, question_en, question_ta, option_a_en, option_a_ta, option_b_en, option_b_ta, option_c_en, option_c_ta, option_d_en, option_d_ta, correct_answer, explanation_en, explanation_ta, tnpsc_tip_en, tnpsc_tip_ta, difficulty) VALUES ('Parliament', 'Polity', 'Polity', 'The maximum strength of the Lok Sabha as laid down in the Constitution is:', 'அரசியலமைப்பில் குறிப்பிடப்பட்டுள்ள லோக்சபாவின் அதிகபட்ச வலிமை:', '545', '545', '550', '550', '552', '552', '543', '543', 'C', NULL, NULL, NULL, NULL, 'MEDIUM');
INSERT INTO questions (topic, subject, category, question_en, question_ta, option_a_en, option_a_ta, option_b_en, option_b_ta, option_c_en, option_c_ta, option_d_en, option_d_ta, correct_answer, explanation_en, explanation_ta, tnpsc_tip_en, tnpsc_tip_ta, difficulty) VALUES ('Parliament', 'Polity', 'Polity', 'A Money Bill under Article 110 of the Indian Constitution can be introduced only in:', 'இந்திய அரசியலமைப்பின் சட்டப்பிரிவு 110 இன் கீழ் பண மசோதா எங்கு மட்டுமே அறிமுகப்படுத்தப்படலாம்?', 'Rajya Sabha', 'ராஜ்யசபா', 'Lok Sabha', 'லோக்சபா', 'Either House', 'எந்த சபையிலும்', 'Joint Session of Parliament', 'நாடாளுமன்றத்தின் கூட்டு அமர்வு', 'B', NULL, NULL, NULL, NULL, 'MEDIUM');
INSERT INTO questions (topic, subject, category, question_en, question_ta, option_a_en, option_a_ta, option_b_en, option_b_ta, option_c_en, option_c_ta, option_d_en, option_d_ta, correct_answer, explanation_en, explanation_ta, tnpsc_tip_en, tnpsc_tip_ta, difficulty) VALUES ('Parliament', 'Polity', 'Polity', 'Which of the following statements about the Rajya Sabha is correct?', 'ராஜ்யசபா பற்றிய பின்வரும் கூற்றுகளில் எது சரியானது?', 'Rajya Sabha can be dissolved by the President', 'ராஜ்யசபாவை குடியரசுத் தலைவர் கலைக்கலாம்', 'Rajya Sabha is a permanent house and cannot be dissolved', 'ராஜ்யசபா ஒரு நிரந்தர அவை மற்றும் அதை கலைக்க முடியாது', 'All members of Rajya Sabha are elected', 'ராஜ்யசபாவின் அனைத்து உறுப்பினர்களும் தேர்ந்தெடுக்கப்படுகிறார்கள்', 'Rajya Sabha consists of 250 elected members', 'ராஜ்யசபாவில் 250 தேர்ந்தெடுக்கப்பட்ட உறுப்பினர்கள் உள்ளனர்', 'B', NULL, NULL, NULL, NULL, 'MEDIUM');
INSERT INTO questions (topic, subject, category, question_en, question_ta, option_a_en, option_a_ta, option_b_en, option_b_ta, option_c_en, option_c_ta, option_d_en, option_d_ta, correct_answer, explanation_en, explanation_ta, tnpsc_tip_en, tnpsc_tip_ta, difficulty) VALUES ('Parliament', 'Polity', 'Polity', 'Consider the following statements about the Speaker of the Lok Sabha: 1. The Speaker is elected by the members of the Lok Sabha. 2. The Speaker casts a vote only in the case of a tie. 3. The Speaker''s office does not fall vacant when the Lok Sabha is dissolved. Which of the above statements are correct?', 'லோக்சபா சபாநாயகர் பற்றிய பின்வரும் கூற்றுகளை கவனியுங்கள்: 1. சபாநாயகர் லோக்சபா உறுப்பினர்களால் தேர்ந்தெடுக்கப்படுகிறார். 2. சபாநாயகர் ஒரு சமநிலை ஏற்படும் போது மட்டுமே வாக்களிக்கிறார். 3. லோக்சபா கலைக்கப்படும் போது சபாநாயகர் பதவி காலியாவதில்லை. மேலே உள்ள கூற்றுகளில் எவை சரியானவை?', '1 and 2 only', '1 மற்றும் 2 மட்டும்', '2 and 3 only', '2 மற்றும் 3 மட்டும்', '1 and 3 only', '1 மற்றும் 3 மட்டும்', '1, 2 and 3', '1, 2 மற்றும் 3', 'D', NULL, NULL, NULL, NULL, 'MEDIUM');
INSERT INTO questions (topic, subject, category, question_en, question_ta, option_a_en, option_a_ta, option_b_en, option_b_ta, option_c_en, option_c_ta, option_d_en, option_d_ta, correct_answer, explanation_en, explanation_ta, tnpsc_tip_en, tnpsc_tip_ta, difficulty) VALUES ('Parliament', 'Polity', 'Polity', 'Under which Article does the President address a joint sitting of both Houses of Parliament?', 'எந்த சட்டப்பிரிவின் கீழ் குடியரசுத் தலைவர் நாடாளுமன்றத்தின் இரு சபைகளின் கூட்டு அமர்வில் உரையாற்றுகிறார்?', 'Article 85', 'சட்டப்பிரிவு 85', 'Article 87', 'சட்டப்பிரிவு 87', 'Article 86', 'சட்டப்பிரிவு 86', 'Article 108', 'சட்டப்பிரிவு 108', 'B', NULL, NULL, NULL, NULL, 'MEDIUM');
INSERT INTO questions (topic, subject, category, question_en, question_ta, option_a_en, option_a_ta, option_b_en, option_b_ta, option_c_en, option_c_ta, option_d_en, option_d_ta, correct_answer, explanation_en, explanation_ta, tnpsc_tip_en, tnpsc_tip_ta, difficulty) VALUES ('Parliament', 'Polity', 'Polity', 'The minimum age required to become a member of the Rajya Sabha is:', 'ராஜ்யசபா உறுப்பினராக ஆவதற்கு தேவையான குறைந்தபட்ச வயது:', '21 years', '21 ஆண்டுகள்', '25 years', '25 ஆண்டுகளில்', '30 years', '30 ஆண்டுகள்', '35 years', '35 ஆண்டுகள்', 'C', NULL, NULL, NULL, NULL, 'MEDIUM');
INSERT INTO questions (topic, subject, category, question_en, question_ta, option_a_en, option_a_ta, option_b_en, option_b_ta, option_c_en, option_c_ta, option_d_en, option_d_ta, correct_answer, explanation_en, explanation_ta, tnpsc_tip_en, tnpsc_tip_ta, difficulty) VALUES ('President', 'Polity', 'Polity', 'The President of India is elected by:', 'இந்தியாவின் குடியரசுத் தலைவர் யாரால் தேர்ந்தெடுக்கப்படுகிறார்?', 'All members of Parliament', 'நாடாளுமன்றத்தின் அனைத்து உறுப்பினர்களும்', 'Elected members of Parliament and elected members of State Legislative Assemblies', 'நாடாளுமன்றத்தின் தேர்ந்தெடுக்கப்பட்ட உறுப்பினர்கள் மற்றும் மாநில சட்டமன்றங்களின் தேர்ந்தெடுக்கப்பட்ட உறுப்பினர்கள்', 'Members of Lok Sabha only', 'லோக்சபா உறுப்பினர்கள் மட்டுமே', 'All citizens of India above 18 years', '18 வயதுக்கு மேற்பட்ட இந்தியாவின் அனைத்து குடிமக்களும்', 'B', NULL, NULL, NULL, NULL, 'MEDIUM');
INSERT INTO questions (topic, subject, category, question_en, question_ta, option_a_en, option_a_ta, option_b_en, option_b_ta, option_c_en, option_c_ta, option_d_en, option_d_ta, correct_answer, explanation_en, explanation_ta, tnpsc_tip_en, tnpsc_tip_ta, difficulty) VALUES ('President', 'Polity', 'Polity', 'Under which Article of the Constitution can the President promulgate an Ordinance when Parliament is not in session?', 'நாடாளுமன்றம் கூட்டத்தொடரில் இல்லாதபோது குடியரசுத் தலைவர் ஓர் அவசரச் சட்டத்தை (Ordinance) பிறப்பிக்க அரசியலமைப்பின் எந்த சட்டப்பிரிவின் கீழ் முடியும்?', 'Article 118', 'சட்டப்பிரிவு 118', 'Article 123', 'சட்டப்பிரிவு 123', 'Article 124', 'சட்டப்பிரிவு 124', 'Article 143', 'சட்டப்பிரிவு 143', 'B', NULL, NULL, NULL, NULL, 'MEDIUM');
INSERT INTO questions (topic, subject, category, question_en, question_ta, option_a_en, option_a_ta, option_b_en, option_b_ta, option_c_en, option_c_ta, option_d_en, option_d_ta, correct_answer, explanation_en, explanation_ta, tnpsc_tip_en, tnpsc_tip_ta, difficulty) VALUES ('President', 'Polity', 'Polity', 'Who administers the oath of office to the President of India?', 'இந்தியாவின் குடியரசுத் தலைவருக்கு பதவியேற்பு சத்தியப்பிரமாணம் யார் வழங்குகிறார்?', 'Prime Minister', 'பிரதமர்', 'Speaker of Lok Sabha', 'லோக்சபா சபாநாயகர்', 'Chief Justice of India', 'இந்தியாவின் தலைமை நீதிபதி', 'Vice-President', 'துணை குடியரசுத் தலைவர்', 'C', NULL, NULL, NULL, NULL, 'MEDIUM');
INSERT INTO questions (topic, subject, category, question_en, question_ta, option_a_en, option_a_ta, option_b_en, option_b_ta, option_c_en, option_c_ta, option_d_en, option_d_ta, correct_answer, explanation_en, explanation_ta, tnpsc_tip_en, tnpsc_tip_ta, difficulty) VALUES ('President', 'Polity', 'Polity', 'The President of India can be removed from office by the process of:', 'இந்தியாவின் குடியரசுத் தலைவரை எந்த செயல்முறை மூலம் பதவியிலிருந்து நீக்கலாம்?', 'No Confidence Motion', 'நம்பிக்கையில்லா தீர்மானம்', 'Impeachment', 'பதவி நீக்க விசாரணை (இம்பீச்மென்ட்)', 'Recall by Electoral College', 'தேர்தல் கல்லூரியால் திரும்பப் பெறுதல்', 'Simple majority in both Houses', 'இரு சபைகளிலும் எளிய பெரும்பான்மை', 'B', NULL, NULL, NULL, NULL, 'MEDIUM');
INSERT INTO questions (topic, subject, category, question_en, question_ta, option_a_en, option_a_ta, option_b_en, option_b_ta, option_c_en, option_c_ta, option_d_en, option_d_ta, correct_answer, explanation_en, explanation_ta, tnpsc_tip_en, tnpsc_tip_ta, difficulty) VALUES ('President', 'Polity', 'Polity', 'Under Article 143, the President can seek the advisory opinion of the Supreme Court. This is called the:', 'சட்டப்பிரிவு 143 இன் கீழ், குடியரசுத் தலைவர் உச்சநீதிமன்றத்தின் ஆலோசனை கருத்தை நாடலாம். இது என்று அழைக்கப்படுகிறது:', 'Judicial Review', 'நீதித்துறை மறுஆய்வு', 'Reference Jurisdiction', 'குறிப்பு அதிகார வரம்பு', 'Advisory Jurisdiction', 'ஆலோசனை அதிகார வரம்பு', 'Writ Jurisdiction', 'ரிட் அதிகார வரம்பு', 'C', NULL, NULL, NULL, NULL, 'MEDIUM');
INSERT INTO questions (topic, subject, category, question_en, question_ta, option_a_en, option_a_ta, option_b_en, option_b_ta, option_c_en, option_c_ta, option_d_en, option_d_ta, correct_answer, explanation_en, explanation_ta, tnpsc_tip_en, tnpsc_tip_ta, difficulty) VALUES ('Judiciary', 'Polity', 'Polity', 'The doctrine of ''Basic Structure'' of the Constitution was propounded in which landmark case?', 'அரசியலமைப்பின் ''அடிப்படை கட்டமைப்பு'' கோட்பாடு எந்த ஒப்பிடற்கரிய வழக்கில் முன்வைக்கப்பட்டது?', 'Golaknath v. State of Punjab (1967)', 'கோலக்நாத் எதிர் பஞ்சாப் மாநிலம் (1967)', 'Kesavananda Bharati v. State of Kerala (1973)', 'கேசவானந்த பாரதி எதிர் கேரள மாநிலம் (1973)', 'Minerva Mills v. Union of India (1980)', 'மினர்வா மில்ஸ் எதிர் இந்திய ஒன்றியம் (1980)', 'Maneka Gandhi v. Union of India (1978)', 'மனேகா காந்தி எதிர் இந்திய ஒன்றியம் (1978)', 'B', NULL, NULL, NULL, NULL, 'MEDIUM');
INSERT INTO questions (topic, subject, category, question_en, question_ta, option_a_en, option_a_ta, option_b_en, option_b_ta, option_c_en, option_c_ta, option_d_en, option_d_ta, correct_answer, explanation_en, explanation_ta, tnpsc_tip_en, tnpsc_tip_ta, difficulty) VALUES ('Judiciary', 'Polity', 'Polity', 'Which Article of the Constitution deals with the original jurisdiction of the Supreme Court?', 'அரசியலமைப்பின் எந்த சட்டப்பிரிவு உச்சநீதிமன்றத்தின் அசல் அதிகார வரம்பை கையாள்கிறது?', 'Article 131', 'சட்டப்பிரிவு 131', 'Article 132', 'சட்டப்பிரிவு 132', 'Article 133', 'சட்டப்பிரிவு 133', 'Article 136', 'சட்டப்பிரிவு 136', 'A', NULL, NULL, NULL, NULL, 'MEDIUM');
INSERT INTO questions (topic, subject, category, question_en, question_ta, option_a_en, option_a_ta, option_b_en, option_b_ta, option_c_en, option_c_ta, option_d_en, option_d_ta, correct_answer, explanation_en, explanation_ta, tnpsc_tip_en, tnpsc_tip_ta, difficulty) VALUES ('Judiciary', 'Polity', 'Polity', 'Judges of the Supreme Court of India hold office until they attain the age of:', 'இந்தியாவின் உச்சநீதிமன்ற நீதிபதிகள் எத்தனை வயது வரை பதவியில் இருக்கிறார்கள்?', '60 years', '60 ஆண்டுகள்', '62 years', '62 ஆண்டுகள்', '65 years', '65 ஆண்டுகள்', '68 years', '68 ஆண்டுகள்', 'C', NULL, NULL, NULL, NULL, 'MEDIUM');
INSERT INTO questions (topic, subject, category, question_en, question_ta, option_a_en, option_a_ta, option_b_en, option_b_ta, option_c_en, option_c_ta, option_d_en, option_d_ta, correct_answer, explanation_en, explanation_ta, tnpsc_tip_en, tnpsc_tip_ta, difficulty) VALUES ('Judiciary', 'Polity', 'Polity', 'Consider the following statements regarding Judicial Review in India: 1. Judicial Review is explicitly mentioned in the Constitution. 2. The Supreme Court can strike down laws that violate Fundamental Rights. 3. Judicial Review extends only to Central laws and not State laws. Which of the above statements is/are correct?', 'இந்தியாவில் நீதித்துறை மறுஆய்வு குறித்த பின்வரும் கூற்றுகளை கவனியுங்கள்: 1. நீதித்துறை மறுஆய்வு அரசியலமைப்பில் வெளிப்படையாக குறிப்பிடப்பட்டுள்ளது. 2. அடிப்படை உரிமைகளை மீறும் சட்டங்களை உச்சநீதிமன்றம் ரத்து செய்யலாம். 3. நீதித்துறை மறுஆய்வு மத்திய சட்டங்களுக்கு மட்டுமே பொருந்தும், மாநில சட்டங்களுக்கு அல்ல. மேலே உள்ள கூற்றுகளில் எது/எவை சரியானது?', '2 only', '2 மட்டும்', '1 and 2 only', '1 மற்றும் 2 மட்டும்', '1 and 3 only', '1 மற்றும் 3 மட்டும்', '1, 2 and 3', '1, 2 மற்றும் 3', 'A', NULL, NULL, NULL, NULL, 'MEDIUM');
INSERT INTO questions (topic, subject, category, question_en, question_ta, option_a_en, option_a_ta, option_b_en, option_b_ta, option_c_en, option_c_ta, option_d_en, option_d_ta, correct_answer, explanation_en, explanation_ta, tnpsc_tip_en, tnpsc_tip_ta, difficulty) VALUES ('Judiciary', 'Polity', 'Polity', 'Public Interest Litigation (PIL) in India was introduced and developed primarily by which Chief Justice?', 'இந்தியாவில் பொது நல வழக்கு (PIL) முதன்மையாக எந்த தலைமை நீதிபதியால் அறிமுகப்படுத்தப்பட்டு வளர்க்கப்பட்டது?', 'Justice Y.V. Chandrachud', 'நீதிபதி வை.வி. சந்திரசூட்', 'Justice P.N. Bhagwati', 'நீதிபதி பி.என். பகவதி', 'Justice M. Hidayatullah', 'நீதிபதி எம். ஹிதாயதுல்லா', 'Justice V.R. Krishna Iyer', 'நீதிபதி வி.ஆர். கிருஷ்ண ஐயர்', 'B', NULL, NULL, NULL, NULL, 'MEDIUM');
INSERT INTO questions (topic, subject, category, question_en, question_ta, option_a_en, option_a_ta, option_b_en, option_b_ta, option_c_en, option_c_ta, option_d_en, option_d_ta, correct_answer, explanation_en, explanation_ta, tnpsc_tip_en, tnpsc_tip_ta, difficulty) VALUES ('DPSP', 'Polity', 'Polity', 'The Directive Principles of State Policy (DPSP) are contained in which Part of the Indian Constitution?', 'மாநிலக் கொள்கையின் வழிகாட்டு நெறிகள் (DPSP) இந்திய அரசியலமைப்பின் எந்த பகுதியில் உள்ளன?', 'Part III', 'பகுதி III', 'Part IV', 'பகுதி IV', 'Part IVA', 'பகுதி IVA', 'Part V', 'பகுதி V', 'B', NULL, NULL, NULL, NULL, 'MEDIUM');
INSERT INTO questions (topic, subject, category, question_en, question_ta, option_a_en, option_a_ta, option_b_en, option_b_ta, option_c_en, option_c_ta, option_d_en, option_d_ta, correct_answer, explanation_en, explanation_ta, tnpsc_tip_en, tnpsc_tip_ta, difficulty) VALUES ('DPSP', 'Polity', 'Polity', 'Which Article of the Constitution directs the State to secure for all workers a living wage and conditions of work ensuring a decent standard of life?', 'அரசியலமைப்பின் எந்த சட்டப்பிரிவு அனைத்து தொழிலாளர்களுக்கும் ஒரு கௌரவமான வாழ்க்கை தரத்தை உறுதி செய்யும் உயிர்ப்பாக்கும் ஊதியத்தையும் வேலை நிலைமைகளையும் மாநிலம் உறுதி செய்யுமாறு வழிகாட்டுகிறது?', 'Article 39', 'சட்டப்பிரிவு 39', 'Article 43', 'சட்டப்பிரிவு 43', 'Article 44', 'சட்டப்பிரிவு 44', 'Article 45', 'சட்டப்பிரிவு 45', 'B', NULL, NULL, NULL, NULL, 'MEDIUM');
INSERT INTO questions (topic, subject, category, question_en, question_ta, option_a_en, option_a_ta, option_b_en, option_b_ta, option_c_en, option_c_ta, option_d_en, option_d_ta, correct_answer, explanation_en, explanation_ta, tnpsc_tip_en, tnpsc_tip_ta, difficulty) VALUES ('DPSP', 'Polity', 'Polity', 'The Directive Principles of State Policy were borrowed from the Constitution of which country?', 'மாநிலக் கொள்கையின் வழிகாட்டு நெறிகள் எந்த நாட்டின் அரசியலமைப்பிலிருந்து எடுக்கப்பட்டன?', 'USA', 'அமெரிக்கா', 'UK', 'இங்கிலாந்து', 'Ireland', 'அயர்லாந்து', 'Canada', 'கனடா', 'C', NULL, NULL, NULL, NULL, 'MEDIUM');
INSERT INTO questions (topic, subject, category, question_en, question_ta, option_a_en, option_a_ta, option_b_en, option_b_ta, option_c_en, option_c_ta, option_d_en, option_d_ta, correct_answer, explanation_en, explanation_ta, tnpsc_tip_en, tnpsc_tip_ta, difficulty) VALUES ('DPSP', 'Polity', 'Polity', 'Article 44 of the Constitution directs the State to secure for the citizens a Uniform Civil Code. Under which classification of DPSPs does Article 44 fall?', 'அரசியலமைப்பின் சட்டப்பிரிவு 44 குடிமக்களுக்கு ஒரே சீரான குடிமை சட்டத்தை உறுதிப்படுத்துமாறு மாநிலத்திற்கு வழிகாட்டுகிறது. DPSP இன் எந்த வகைப்பாட்டின் கீழ் சட்டப்பிரிவு 44 வருகிறது?', 'Gandhian Principles', 'காந்தியன் கொள்கைகள்', 'Liberal-Intellectual Principles', 'தாராளவாத-அறிவுஜீவி கொள்கைகள்', 'Socialistic Principles', 'சோசலிஸ்ட் கொள்கைகள்', 'Economic Principles', 'பொருளாதார கொள்கைகள்', 'B', NULL, NULL, NULL, NULL, 'MEDIUM');
INSERT INTO questions (topic, subject, category, question_en, question_ta, option_a_en, option_a_ta, option_b_en, option_b_ta, option_c_en, option_c_ta, option_d_en, option_d_ta, correct_answer, explanation_en, explanation_ta, tnpsc_tip_en, tnpsc_tip_ta, difficulty) VALUES ('DPSP', 'Polity', 'Polity', 'Assertion (A): Directive Principles of State Policy are non-justiciable. Reason (R): They cannot be enforced through courts of law. Choose the correct option:', 'கூற்று (A): மாநிலக் கொள்கையின் வழிகாட்டு நெறிகள் நீதிமன்றத்தில் அமல்படுத்த முடியாதவை. காரணம் (R): அவற்றை சட்ட நீதிமன்றங்கள் மூலம் அமல்படுத்த முடியாது. சரியான விருப்பத்தை தேர்ந்தெடுங்கள்:', 'A is correct and R is the correct explanation of A', 'A சரியானது மற்றும் R என்பது A இன் சரியான விளக்கம்', 'A is correct but R is not the correct explanation of A', 'A சரியானது ஆனால் R என்பது A இன் சரியான விளக்கம் இல்லை', 'Both A and R are incorrect', 'A மற்றும் R இரண்டும் தவறானவை', 'A is incorrect but R is correct', 'A தவறானது ஆனால் R சரியானது', 'A', NULL, NULL, NULL, NULL, 'MEDIUM');
INSERT INTO questions (topic, subject, category, question_en, question_ta, option_a_en, option_a_ta, option_b_en, option_b_ta, option_c_en, option_c_ta, option_d_en, option_d_ta, correct_answer, explanation_en, explanation_ta, tnpsc_tip_en, tnpsc_tip_ta, difficulty) VALUES ('Constitutional Amendments', 'Polity', 'Polity', 'Which Constitutional Amendment is known as the ''Mini Constitution'' of India?', 'எந்த அரசியலமைப்பு திருத்தம் இந்தியாவின் ''மினி அரசியலமைப்பு'' என்று அறியப்படுகிறது?', '42nd Amendment Act, 1976', '42வது திருத்தச் சட்டம், 1976', '44th Amendment Act, 1978', '44வது திருத்தச் சட்டம், 1978', '74th Amendment Act, 1992', '74வது திருத்தச் சட்டம், 1992', '86th Amendment Act, 2002', '86வது திருத்தச் சட்டம், 2002', 'A', NULL, NULL, NULL, NULL, 'MEDIUM');
INSERT INTO questions (topic, subject, category, question_en, question_ta, option_a_en, option_a_ta, option_b_en, option_b_ta, option_c_en, option_c_ta, option_d_en, option_d_ta, correct_answer, explanation_en, explanation_ta, tnpsc_tip_en, tnpsc_tip_ta, difficulty) VALUES ('Constitutional Amendments', 'Polity', 'Polity', 'The words ''Socialist'', ''Secular'', and ''Integrity'' were added to the Preamble of the Constitution by which Amendment?', '''சோசலிஸ்ட்'', ''மதச்சார்பற்ற'' மற்றும் ''ஒருமைப்பாடு'' என்ற வார்த்தைகள் எந்த திருத்தத்தால் அரசியலமைப்பின் முன்னுரையில் சேர்க்கப்பட்டன?', '40th Amendment', '40வது திருத்தம்', '42nd Amendment', '42வது திருத்தம்', '44th Amendment', '44வது திருத்தம்', '52nd Amendment', '52வது திருத்தம்', 'B', NULL, NULL, NULL, NULL, 'MEDIUM');
INSERT INTO questions (topic, subject, category, question_en, question_ta, option_a_en, option_a_ta, option_b_en, option_b_ta, option_c_en, option_c_ta, option_d_en, option_d_ta, correct_answer, explanation_en, explanation_ta, tnpsc_tip_en, tnpsc_tip_ta, difficulty) VALUES ('Constitutional Amendments', 'Polity', 'Polity', 'The Anti-Defection Law was added to the Constitution by the:', 'கட்சி விலகல் எதிர்ப்புச் சட்டம் அரசியலமைப்பில் எதன் மூலம் சேர்க்கப்பட்டது?', '42nd Amendment Act, 1976', '42வது திருத்தச் சட்டம், 1976', '44th Amendment Act, 1978', '44வது திருத்தச் சட்டம், 1978', '52nd Amendment Act, 1985', '52வது திருத்தச் சட்டம், 1985', '61st Amendment Act, 1988', '61வது திருத்தச் சட்டம், 1988', 'C', NULL, NULL, NULL, NULL, 'MEDIUM');
INSERT INTO questions (topic, subject, category, question_en, question_ta, option_a_en, option_a_ta, option_b_en, option_b_ta, option_c_en, option_c_ta, option_d_en, option_d_ta, correct_answer, explanation_en, explanation_ta, tnpsc_tip_en, tnpsc_tip_ta, difficulty) VALUES ('Constitutional Amendments', 'Polity', 'Polity', 'Consider the following about the 44th Constitutional Amendment Act, 1978: 1. It restored the Right to Property as a Fundamental Right. 2. It made the Right to Life more meaningful by connecting it with livelihood. 3. It restricted the power of the President to proclaim National Emergency. Which of the above is/are correct?', '44வது அரசியலமைப்பு திருத்தச் சட்டம், 1978 பற்றிய பின்வருவனவற்றை கவனியுங்கள்: 1. இது சொத்து உரிமையை அடிப்படை உரிமையாக மீட்டெடுத்தது. 2. இது வாழ்வாதாரத்துடன் இணைப்பதன் மூலம் உயிர் உரிமையை மிகவும் அர்த்தமுள்ளதாக ஆக்கியது. 3. இது தேசிய அவசரநிலையை பிரகடனப்படுத்தும் குடியரசுத் தலைவரின் அதிகாரத்தை கட்டுப்படுத்தியது. மேலே உள்ளவற்றில் எது/எவை சரியானது?', '1 only', '1 மட்டும்', '2 only', '2 மட்டும்', '3 only', '3 மட்டும்', '2 and 3 only', '2 மற்றும் 3 மட்டும்', 'C', NULL, NULL, NULL, NULL, 'MEDIUM');
INSERT INTO questions (topic, subject, category, question_en, question_ta, option_a_en, option_a_ta, option_b_en, option_b_ta, option_c_en, option_c_ta, option_d_en, option_d_ta, correct_answer, explanation_en, explanation_ta, tnpsc_tip_en, tnpsc_tip_ta, difficulty) VALUES ('Constitutional Amendments', 'Polity', 'Polity', 'Which Amendment to the Constitution lowered the voting age from 21 to 18 years?', 'எந்த அரசியலமைப்பு திருத்தம் வாக்களிக்கும் வயதை 21 இலிருந்து 18 ஆண்டுகளாக குறைத்தது?', '52nd Amendment', '52வது திருத்தம்', '61st Amendment', '61வது திருத்தம்', '73rd Amendment', '73வது திருத்தம்', '74th Amendment', '74வது திருத்தம்', 'B', NULL, NULL, NULL, NULL, 'MEDIUM');
INSERT INTO questions (topic, subject, category, question_en, question_ta, option_a_en, option_a_ta, option_b_en, option_b_ta, option_c_en, option_c_ta, option_d_en, option_d_ta, correct_answer, explanation_en, explanation_ta, tnpsc_tip_en, tnpsc_tip_ta, difficulty) VALUES ('Emergency Provisions', 'Polity', 'Polity', 'Under which Article of the Constitution can the President proclaim a National Emergency?', 'அரசியலமைப்பின் எந்த சட்டப்பிரிவின் கீழ் குடியரசுத் தலைவர் தேசிய அவசரநிலையை பிரகடனப்படுத்தலாம்?', 'Article 352', 'சட்டப்பிரிவு 352', 'Article 356', 'சட்டப்பிரிவு 356', 'Article 360', 'சட்டப்பிரிவு 360', 'Article 370', 'சட்டப்பிரிவு 370', 'A', NULL, NULL, NULL, NULL, 'MEDIUM');
INSERT INTO questions (topic, subject, category, question_en, question_ta, option_a_en, option_a_ta, option_b_en, option_b_ta, option_c_en, option_c_ta, option_d_en, option_d_ta, correct_answer, explanation_en, explanation_ta, tnpsc_tip_en, tnpsc_tip_ta, difficulty) VALUES ('Emergency Provisions', 'Polity', 'Polity', 'During a National Emergency, which Fundamental Right CANNOT be suspended even by a Presidential Proclamation?', 'தேசிய அவசரநிலையின் போது, குடியரசுத் தலைவரின் பிரகடனத்தால் கூட எந்த அடிப்படை உரிமையை இடைநிறுத்த முடியாது?', 'Right to Freedom of Speech', 'பேச்சு சுதந்திர உரிமை', 'Right to Life and Personal Liberty under Article 21', 'சட்டப்பிரிவு 21 இன் கீழ் உயிர் மற்றும் தனி சுதந்திர உரிமை', 'Right to move freely throughout India', 'இந்தியா முழுவதும் சுதந்திரமாக நகரும் உரிமை', 'Right to Equality under Article 14 and 21 are non-suspendable', 'சட்டப்பிரிவு 14 மற்றும் 21 இன் கீழ் சமத்துவ உரிமை இடைநிறுத்த முடியாதது', 'B', NULL, NULL, NULL, NULL, 'MEDIUM');
INSERT INTO questions (topic, subject, category, question_en, question_ta, option_a_en, option_a_ta, option_b_en, option_b_ta, option_c_en, option_c_ta, option_d_en, option_d_ta, correct_answer, explanation_en, explanation_ta, tnpsc_tip_en, tnpsc_tip_ta, difficulty) VALUES ('Emergency Provisions', 'Polity', 'Polity', 'State Emergency (President''s Rule) is imposed under which Article of the Constitution?', 'மாநில அவசரநிலை (குடியரசுத் தலைவர் ஆட்சி) அரசியலமைப்பின் எந்த சட்டப்பிரிவின் கீழ் விதிக்கப்படுகிறது?', 'Article 352', 'சட்டப்பிரிவு 352', 'Article 355', 'சட்டப்பிரிவு 355', 'Article 356', 'சட்டப்பிரிவு 356', 'Article 360', 'சட்டப்பிரிவு 360', 'C', NULL, NULL, NULL, NULL, 'MEDIUM');
INSERT INTO questions (topic, subject, category, question_en, question_ta, option_a_en, option_a_ta, option_b_en, option_b_ta, option_c_en, option_c_ta, option_d_en, option_d_ta, correct_answer, explanation_en, explanation_ta, tnpsc_tip_en, tnpsc_tip_ta, difficulty) VALUES ('Emergency Provisions', 'Polity', 'Polity', 'The Financial Emergency under Article 360 has been imposed in India how many times so far?', 'சட்டப்பிரிவு 360 இன் கீழ் நிதி அவசரநிலை இதுவரை இந்தியாவில் எத்தனை முறை விதிக்கப்பட்டுள்ளது?', 'Once', 'ஒரு முறை', 'Twice', 'இரண்டு முறை', 'Three times', 'மூன்று முறை', 'Never', 'ஒருபோதும் இல்லை', 'D', NULL, NULL, NULL, NULL, 'MEDIUM');
INSERT INTO questions (topic, subject, category, question_en, question_ta, option_a_en, option_a_ta, option_b_en, option_b_ta, option_c_en, option_c_ta, option_d_en, option_d_ta, correct_answer, explanation_en, explanation_ta, tnpsc_tip_en, tnpsc_tip_ta, difficulty) VALUES ('Emergency Provisions', 'Polity', 'Polity', 'National Emergency declared under Article 352 must be approved by both Houses of Parliament within:', 'சட்டப்பிரிவு 352 இன் கீழ் பிரகடனப்படுத்தப்பட்ட தேசிய அவசரநிலை நாடாளுமன்றத்தின் இரு சபைகளாலும் எத்தனை நாட்களுக்குள் ஒப்புதல் அளிக்கப்பட வேண்டும்?', '14 days', '14 நாட்கள்', '30 days', '30 நாட்கள்', '1 month', '1 மாதம்', '2 months', '2 மாதங்கள்', 'B', NULL, NULL, NULL, NULL, 'MEDIUM');
INSERT INTO questions (topic, subject, category, question_en, question_ta, option_a_en, option_a_ta, option_b_en, option_b_ta, option_c_en, option_c_ta, option_d_en, option_d_ta, correct_answer, explanation_en, explanation_ta, tnpsc_tip_en, tnpsc_tip_ta, difficulty) VALUES ('Emergency Provisions', 'Polity', 'Polity', 'Which of the following is NOT a ground for declaring National Emergency under Article 352 after the 44th Amendment Act?', '44வது திருத்தச் சட்டத்திற்கு பிறகு சட்டப்பிரிவு 352 இன் கீழ் தேசிய அவசரநிலையை பிரகடனப்படுத்துவதற்கான காரணமாக பின்வருவனவற்றில் எது இல்லை?', 'War', 'போர்', 'External Aggression', 'வெளி ஆக்கிரமிப்பு', 'Armed Rebellion', 'ஆயுத கிளர்ச்சி', 'Internal Disturbance', 'உள் கலவரம்', 'D', NULL, NULL, NULL, NULL, 'MEDIUM');
INSERT INTO questions (topic, subject, category, question_en, question_ta, option_a_en, option_a_ta, option_b_en, option_b_ta, option_c_en, option_c_ta, option_d_en, option_d_ta, correct_answer, explanation_en, explanation_ta, tnpsc_tip_en, tnpsc_tip_ta, difficulty) VALUES ('Local Government', 'Polity', 'Polity', 'The 73rd Constitutional Amendment Act, 1992 added which Schedule to the Constitution dealing with Panchayati Raj institutions?', '73வது அரசியலமைப்பு திருத்தச் சட்டம், 1992 பஞ்சாயத்து ராஜ் நிறுவனங்களை கையாளும் எந்த அட்டவணையை அரசியலமைப்பில் சேர்த்தது?', '10th Schedule', '10வது அட்டவணை', '11th Schedule', '11வது அட்டவணை', '12th Schedule', '12வது அட்டவணை', '9th Schedule', '9வது அட்டவணை', 'B', NULL, NULL, NULL, NULL, 'MEDIUM');
INSERT INTO questions (topic, subject, category, question_en, question_ta, option_a_en, option_a_ta, option_b_en, option_b_ta, option_c_en, option_c_ta, option_d_en, option_d_ta, correct_answer, explanation_en, explanation_ta, tnpsc_tip_en, tnpsc_tip_ta, difficulty) VALUES ('Local Government', 'Polity', 'Polity', 'Which Article of the Constitution mandates the establishment of a State Finance Commission every five years for Panchayati Raj institutions?', 'பஞ்சாயத்து ராஜ் நிறுவனங்களுக்காக ஐந்து ஆண்டுகளுக்கு ஒருமுறை மாநில நிதி ஆணையம் அமைக்க வேண்டும் என்று அரசியலமைப்பின் எந்த சட்டப்பிரிவு கட்டாயப்படுத்துகிறது?', 'Article 243-G', 'சட்டப்பிரிவு 243-G', 'Article 243-H', 'சட்டப்பிரிவு 243-H', 'Article 243-I', 'சட்டப்பிரிவு 243-I', 'Article 243-J', 'சட்டப்பிரிவு 243-J', 'C', NULL, NULL, NULL, NULL, 'MEDIUM');
INSERT INTO questions (topic, subject, category, question_en, question_ta, option_a_en, option_a_ta, option_b_en, option_b_ta, option_c_en, option_c_ta, option_d_en, option_d_ta, correct_answer, explanation_en, explanation_ta, tnpsc_tip_en, tnpsc_tip_ta, difficulty) VALUES ('Local Government', 'Polity', 'Polity', 'Which Amendment Act gave constitutional status to Urban Local Bodies (Municipalities)?', 'எந்த திருத்தச் சட்டம் நகர்ப்புற உள்ளாட்சி அமைப்புகளுக்கு (நகராட்சிகளுக்கு) அரசியலமைப்பு அந்தஸ்தை கொடுத்தது?', '73rd Amendment Act, 1992', '73வது திருத்தச் சட்டம், 1992', '74th Amendment Act, 1992', '74வது திருத்தச் சட்டம், 1992', '72nd Amendment Act, 1992', '72வது திருத்தச் சட்டம், 1992', '75th Amendment Act, 1994', '75வது திருத்தச் சட்டம், 1994', 'B', NULL, NULL, NULL, NULL, 'MEDIUM');
INSERT INTO questions (topic, subject, category, question_en, question_ta, option_a_en, option_a_ta, option_b_en, option_b_ta, option_c_en, option_c_ta, option_d_en, option_d_ta, correct_answer, explanation_en, explanation_ta, tnpsc_tip_en, tnpsc_tip_ta, difficulty) VALUES ('Local Government', 'Polity', 'Polity', 'The Balwant Rai Mehta Committee (1957) recommended which type of Panchayati Raj structure in India?', 'பல்வந்த் ராய் மேத்தா குழு (1957) இந்தியாவில் எந்த வகையான பஞ்சாயத்து ராஜ் கட்டமைப்பை பரிந்துரைத்தது?', 'Single-tier structure', 'ஒற்றை அடுக்கு கட்டமைப்பு', 'Two-tier structure', 'இரண்டு அடுக்கு கட்டமைப்பு', 'Three-tier structure', 'மூன்று அடுக்கு கட்டமைப்பு', 'Four-tier structure', 'நான்கு அடுக்கு கட்டமைப்பு', 'C', NULL, NULL, NULL, NULL, 'MEDIUM');
INSERT INTO questions (topic, subject, category, question_en, question_ta, option_a_en, option_a_ta, option_b_en, option_b_ta, option_c_en, option_c_ta, option_d_en, option_d_ta, correct_answer, explanation_en, explanation_ta, tnpsc_tip_en, tnpsc_tip_ta, difficulty) VALUES ('Local Government', 'Polity', 'Polity', 'Consider the following statements about the 73rd Amendment Act: 1. It provides for reservation of seats for Scheduled Castes, Scheduled Tribes, and Women in Panchayats. 2. Women must get not less than one-third of total seats. 3. The term of Panchayats is fixed at 6 years. Which of the above statements is/are correct?', '73வது திருத்தச் சட்டம் பற்றிய பின்வரும் கூற்றுகளை கவனியுங்கள்: 1. இது பஞ்சாயத்துகளில் தாழ்த்தப்பட்ட சாதியினர், பழங்குடியினர் மற்றும் பெண்களுக்கு இடஒதுக்கீடு வழங்குகிறது. 2. பெண்களுக்கு மொத்த இடங்களில் மூன்றில் ஒரு பங்கிற்கு குறையாமல் கிடைக்க வேண்டும். 3. பஞ்சாயத்துகளின் பதவிக்காலம் 6 ஆண்டுகளாக நிர்ணயிக்கப்பட்டுள்ளது. மேலே உள்ள கூற்றுகளில் எது/எவை சரியானது?', '1 and 2 only', '1 மற்றும் 2 மட்டும்', '2 and 3 only', '2 மற்றும் 3 மட்டும்', '1 only', '1 மட்டும்', '1, 2 and 3', '1, 2 மற்றும் 3', 'A', NULL, NULL, NULL, NULL, 'MEDIUM');
INSERT INTO questions (topic, subject, category, question_en, question_ta, option_a_en, option_a_ta, option_b_en, option_b_ta, option_c_en, option_c_ta, option_d_en, option_d_ta, correct_answer, explanation_en, explanation_ta, tnpsc_tip_en, tnpsc_tip_ta, difficulty) VALUES ('Fundamental Rights', 'Polity', 'Polity', 'Which Part of the Indian Constitution deals with Fundamental Rights?', 'இந்திய அரசியலமைப்பின் எந்த பகுதி அடிப்படை உரிமைகளை கையாள்கிறது?', 'Part II', 'பகுதி II', 'Part III', 'பகுதி III', 'Part IV', 'பகுதி IV', 'Part V', 'பகுதி V', 'B', NULL, NULL, NULL, NULL, 'MEDIUM');
INSERT INTO questions (topic, subject, category, question_en, question_ta, option_a_en, option_a_ta, option_b_en, option_b_ta, option_c_en, option_c_ta, option_d_en, option_d_ta, correct_answer, explanation_en, explanation_ta, tnpsc_tip_en, tnpsc_tip_ta, difficulty) VALUES ('Fundamental Rights', 'Polity', 'Polity', 'Article 25 of the Indian Constitution guarantees freedom of conscience and free profession, practice, and propagation of religion. However, this right is subject to:', 'இந்திய அரசியலமைப்பின் சட்டப்பிரிவு 25 மன சாட்சி சுதந்திரம் மற்றும் சமயத்தை சுதந்திரமாக தொழிலாக கொள்வது, கடைபிடிப்பது மற்றும் பிரச்சாரம் செய்வதற்கான சுதந்திரத்தை உத்தரவாதம் செய்கிறது. இந்த உரிமை எதற்கு உட்பட்டது?', 'Public order, morality, and health', 'பொது ஒழுங்கு, ஒழுக்கம் மற்றும் சுகாதாரம்', 'National security and unity only', 'தேசிய பாதுகாப்பு மற்றும் ஒற்றுமை மட்டுமே', 'Sovereignty and integrity of India only', 'இந்தியாவின் இறையாண்மை மற்றும் ஒருமைப்பாடு மட்டுமே', 'No restrictions apply to this right', 'இந்த உரிமைக்கு எந்த கட்டுப்பாடுகளும் பொருந்தாது', 'A', NULL, NULL, NULL, NULL, 'MEDIUM');
INSERT INTO questions (topic, subject, category, question_en, question_ta, option_a_en, option_a_ta, option_b_en, option_b_ta, option_c_en, option_c_ta, option_d_en, option_d_ta, correct_answer, explanation_en, explanation_ta, tnpsc_tip_en, tnpsc_tip_ta, difficulty) VALUES ('Parliament', 'Polity', 'Polity', 'The President''s Rule in a state cannot continue beyond one year without special approval. What is the maximum period for which President''s Rule can be extended under certain conditions?', 'ஒரு மாநிலத்தில் குடியரசுத் தலைவர் ஆட்சி சிறப்பு ஒப்புதல் இல்லாமல் ஒரு வருடத்திற்கு மேல் தொடர முடியாது. சில நிலைமைகளின் கீழ் குடியரசுத் தலைவர் ஆட்சியை அதிகபட்சம் எவ்வளவு காலம் நீட்டிக்கலாம்?', '2 years', '2 ஆண்டுகள்', '3 years', '3 ஆண்டுகள்', '4 years', '4 ஆண்டுகள்', '5 years', '5 ஆண்டுகள்', 'B', NULL, NULL, NULL, NULL, 'MEDIUM');
INSERT INTO questions (topic, subject, category, question_en, question_ta, option_a_en, option_a_ta, option_b_en, option_b_ta, option_c_en, option_c_ta, option_d_en, option_d_ta, correct_answer, explanation_en, explanation_ta, tnpsc_tip_en, tnpsc_tip_ta, difficulty) VALUES ('President', 'Polity', 'Polity', 'The President of India enjoys ''pocket veto'' power with respect to which type of bill?', 'இந்தியாவின் குடியரசுத் தலைவர் எந்த வகையான மசோதா விஷயத்தில் ''பாக்கெட் வீட்டோ'' அதிகாரத்தை அனுபவிக்கிறார்?', 'Money Bills', 'பண மசோதாக்கள்', 'Constitutional Amendment Bills', 'அரசியலமைப்பு திருத்த மசோதாக்கள்', 'Ordinary Bills other than Money Bills', 'பண மசோதாக்கள் அல்லாத சாதாரண மசோதாக்கள்', 'All types of Bills', 'அனைத்து வகையான மசோதாக்களும்', 'C', NULL, NULL, NULL, NULL, 'MEDIUM');
INSERT INTO questions (topic, subject, category, question_en, question_ta, option_a_en, option_a_ta, option_b_en, option_b_ta, option_c_en, option_c_ta, option_d_en, option_d_ta, correct_answer, explanation_en, explanation_ta, tnpsc_tip_en, tnpsc_tip_ta, difficulty) VALUES ('Judiciary', 'Polity', 'Polity', 'In which case did the Supreme Court hold that the right to privacy is a fundamental right under Article 21?', 'எந்த வழக்கில் உச்சநீதிமன்றம் தனியுரிமை உரிமை சட்டப்பிரிவு 21 இன் கீழ் ஒரு அடிப்படை உரிமை என்று தீர்ப்பளித்தது?', 'Vishaka v. State of Rajasthan (1997)', 'விஷாகா எதிர் ராஜஸ்தான் மாநிலம் (1997)', 'Justice K.S. Puttaswamy v. Union of India (2017)', 'நீதிபதி கே.எஸ். புட்டஸ்வாமி எதிர் இந்திய ஒன்றியம் (2017)', 'Shayara Bano v. Union of India (2017)', 'ஷாயரா பானோ எதிர் இந்திய ஒன்றியம் (2017)', 'Navtej Singh Johar v. Union of India (2018)', 'நவ்தேஜ் சிங் ஜோஹர் எதிர் இந்திய ஒன்றியம் (2018)', 'B', NULL, NULL, NULL, NULL, 'MEDIUM');
INSERT INTO questions (topic, subject, category, question_en, question_ta, option_a_en, option_a_ta, option_b_en, option_b_ta, option_c_en, option_c_ta, option_d_en, option_d_ta, correct_answer, explanation_en, explanation_ta, tnpsc_tip_en, tnpsc_tip_ta, difficulty) VALUES ('DPSP', 'Polity', 'Polity', 'Which Article of the Constitution directs the State to promote cottage industries in rural areas?', 'கிராமப்புற பகுதிகளில் குடிசை தொழில்களை மேம்படுத்த மாநிலத்திற்கு அரசியலமைப்பின் எந்த சட்டப்பிரிவு வழிகாட்டுகிறது?', 'Article 40', 'சட்டப்பிரிவு 40', 'Article 43', 'சட்டப்பிரிவு 43', 'Article 46', 'சட்டப்பிரிவு 46', 'Article 47', 'சட்டப்பிரிவு 47', 'B', NULL, NULL, NULL, NULL, 'MEDIUM');
INSERT INTO questions (topic, subject, category, question_en, question_ta, option_a_en, option_a_ta, option_b_en, option_b_ta, option_c_en, option_c_ta, option_d_en, option_d_ta, correct_answer, explanation_en, explanation_ta, tnpsc_tip_en, tnpsc_tip_ta, difficulty) VALUES ('Constitutional Amendments', 'Polity', 'Polity', 'The procedure for amendment of the Constitution is given in which Article?', 'அரசியலமைப்பு திருத்தத்திற்கான நடைமுறை எந்த சட்டப்பிரிவில் கொடுக்கப்பட்டுள்ளது?', 'Article 352', 'சட்டப்பிரிவு 352', 'Article 360', 'சட்டப்பிரிவு 360', 'Article 368', 'சட்டப்பிரிவு 368', 'Article 370', 'சட்டப்பிரிவு 370', 'C', NULL, NULL, NULL, NULL, 'MEDIUM');
INSERT INTO questions (topic, subject, category, question_en, question_ta, option_a_en, option_a_ta, option_b_en, option_b_ta, option_c_en, option_c_ta, option_d_en, option_d_ta, correct_answer, explanation_en, explanation_ta, tnpsc_tip_en, tnpsc_tip_ta, difficulty) VALUES ('Parliament', 'Polity', 'Polity', 'The quorum required to constitute a meeting of either House of Parliament is:', 'நாடாளுமன்றத்தின் எந்த சபையின் கூட்டத்தையும் நடத்த தேவையான கோரம் (குறைந்தபட்ச எண்ணிக்கை):', '1/5 of the total membership', 'மொத்த உறுப்பினர் எண்ணிக்கையில் 1/5', '1/10 of the total membership', 'மொத்த உறுப்பினர் எண்ணிக்கையில் 1/10', '1/3 of the total membership', 'மொத்த உறுப்பினர் எண்ணிக்கையில் 1/3', '1/4 of the total membership', 'மொத்த உறுப்பினர் எண்ணிக்கையில் 1/4', 'B', NULL, NULL, NULL, NULL, 'MEDIUM');
INSERT INTO questions (topic, subject, category, question_en, question_ta, option_a_en, option_a_ta, option_b_en, option_b_ta, option_c_en, option_c_ta, option_d_en, option_d_ta, correct_answer, explanation_en, explanation_ta, tnpsc_tip_en, tnpsc_tip_ta, difficulty) VALUES ('Fundamental Rights', 'Polity', 'Polity', 'Which Article of the Indian Constitution provides for the Right to Equality before law and equal protection of laws?', 'இந்திய அரசியலமைப்பின் எந்த சட்டப்பிரிவு சட்டத்தின் முன் சமத்துவம் மற்றும் சட்டங்களின் சம பாதுகாப்பு உரிமையை வழங்குகிறது?', 'Article 12', 'சட்டப்பிரிவு 12', 'Article 13', 'சட்டப்பிரிவு 13', 'Article 14', 'சட்டப்பிரிவு 14', 'Article 16', 'சட்டப்பிரிவு 16', 'C', NULL, NULL, NULL, NULL, 'MEDIUM');
INSERT INTO questions (topic, subject, category, question_en, question_ta, option_a_en, option_a_ta, option_b_en, option_b_ta, option_c_en, option_c_ta, option_d_en, option_d_ta, correct_answer, explanation_en, explanation_ta, tnpsc_tip_en, tnpsc_tip_ta, difficulty) VALUES ('Judiciary', 'Polity', 'Polity', 'The concept of ''Judicial Activism'' in India refers to:', 'இந்தியாவில் ''நீதித்துறை செயல்வீரம்'' என்ற கருத்து எதை குறிக்கிறது?', 'The judiciary taking an active role in governance by filling legislative and executive gaps', 'சட்டமன்ற மற்றும் நிர்வாக இடைவெளிகளை நிரப்புவதன் மூலம் நீதித்துறை ஆட்சியில் சுறுசுறுப்பான பங்கு எடுப்பது', 'The judiciary refusing to hear cases involving government decisions', 'அரசாங்க முடிவுகள் சம்பந்தப்பட்ட வழக்குகளை கேட்க நீதித்துறை மறுப்பது', 'The judiciary actively participating in elections', 'நீதித்துறை தேர்தல்களில் சுறுசுறுப்பாக பங்கேற்பது', 'Judges making laws through their personal discretion', 'நீதிபதிகள் தங்கள் தனிப்பட்ட விருப்பு வெறுப்பின் மூலம் சட்டங்களை உருவாக்குவது', 'A', NULL, NULL, NULL, NULL, 'MEDIUM');
INSERT INTO questions (topic, subject, category, question_en, question_ta, option_a_en, option_a_ta, option_b_en, option_b_ta, option_c_en, option_c_ta, option_d_en, option_d_ta, correct_answer, explanation_en, explanation_ta, tnpsc_tip_en, tnpsc_tip_ta, difficulty) VALUES ('Local Government', 'Polity', 'Polity', 'Which committee recommended the establishment of Nyaya Panchayats for the resolution of local disputes at the village level?', 'கிராம மட்டத்தில் உள்ளூர் தகராறுகளை தீர்ப்பதற்காக நியாய பஞ்சாயத்துகளை நிறுவ எந்த குழு பரிந்துரைத்தது?', 'Balwant Rai Mehta Committee', 'பல்வந்த் ராய் மேத்தா குழு', 'Ashok Mehta Committee', 'அசோக் மேத்தா குழு', 'G.V.K. Rao Committee', 'ஜி.வி.கே. ராவ் குழு', 'L.M. Singhvi Committee', 'எல்.எம். சிங்வி குழு', 'D', NULL, NULL, NULL, NULL, 'MEDIUM');
INSERT INTO questions (topic, subject, category, question_en, question_ta, option_a_en, option_a_ta, option_b_en, option_b_ta, option_c_en, option_c_ta, option_d_en, option_d_ta, correct_answer, explanation_en, explanation_ta, tnpsc_tip_en, tnpsc_tip_ta, difficulty) VALUES ('Emergency Provisions', 'Polity', 'Polity', 'Match the following Emergency Provisions with their Articles: National Emergency — (i) Article 360 State Emergency — (ii) Article 352 Financial Emergency — (iii) Article 356 Choose the correct matching:', 'பின்வரும் அவசரநிலை விதிகளை அவற்றின் சட்டப்பிரிவுகளுடன் பொருத்துக: தேசிய அவசரநிலை — (i) சட்டப்பிரிவு 360 மாநில அவசரநிலை — (ii) சட்டப்பிரிவு 352 நிதி அவசரநிலை — (iii) சட்டப்பிரிவு 356 சரியான பொருத்தத்தை தேர்ந்தெடுங்கள்:', 'National-(ii), State-(iii), Financial-(i)', 'தேசியம்-(ii), மாநிலம்-(iii), நிதி-(i)', 'National-(i), State-(ii), Financial-(iii)', 'தேசியம்-(i), மாநிலம்-(ii), நிதி-(iii)', 'National-(iii), State-(i), Financial-(ii)', 'தேசியம்-(iii), மாநிலம்-(i), நிதி-(ii)', 'National-(ii), State-(i), Financial-(iii)', 'தேசியம்-(ii), மாநிலம்-(i), நிதி-(iii)', 'A', NULL, NULL, NULL, NULL, 'MEDIUM');
INSERT INTO questions (topic, subject, category, question_en, question_ta, option_a_en, option_a_ta, option_b_en, option_b_ta, option_c_en, option_c_ta, option_d_en, option_d_ta, correct_answer, explanation_en, explanation_ta, tnpsc_tip_en, tnpsc_tip_ta, difficulty) VALUES ('DPSP', 'Polity', 'Polity', 'Article 40 of the Indian Constitution directs the State to organise:', 'இந்திய அரசியலமைப்பின் சட்டப்பிரிவு 40 மாநிலத்திற்கு எதை ஒழுங்கமைக்க வழிகாட்டுகிறது?', 'Village courts', 'கிராம நீதிமன்றங்கள்', 'Village Panchayats', 'கிராம பஞ்சாயத்துகள்', 'Co-operative societies', 'கூட்டுறவு சங்கங்கள்', 'Trade unions', 'தொழிற்சங்கங்கள்', 'B', NULL, NULL, NULL, NULL, 'MEDIUM');
INSERT INTO questions (topic, subject, category, question_en, question_ta, option_a_en, option_a_ta, option_b_en, option_b_ta, option_c_en, option_c_ta, option_d_en, option_d_ta, correct_answer, explanation_en, explanation_ta, tnpsc_tip_en, tnpsc_tip_ta, difficulty) VALUES ('Parliament', 'Polity', 'Polity', 'Which of the following Bills CANNOT be introduced in the Rajya Sabha?', 'பின்வரும் மசோதாக்களில் எதை ராஜ்யசபாவில் அறிமுகப்படுத்த முடியாது?', 'Ordinary Bill', 'சாதாரண மசோதா', 'Private Member Bill', 'தனியார் உறுப்பினர் மசோதா', 'Money Bill', 'பண மசோதா', 'Constitutional Amendment Bill', 'அரசியலமைப்பு திருத்த மசோதா', 'C', NULL, NULL, NULL, NULL, 'MEDIUM');
INSERT INTO questions (topic, subject, category, question_en, question_ta, option_a_en, option_a_ta, option_b_en, option_b_ta, option_c_en, option_c_ta, option_d_en, option_d_ta, correct_answer, explanation_en, explanation_ta, tnpsc_tip_en, tnpsc_tip_ta, difficulty) VALUES ('Fundamental Rights', 'Polity', 'Polity', 'Article 15 of the Constitution prohibits discrimination on grounds of religion, race, caste, sex, or place of birth. The State may, however, make special provisions for:', 'அரசியலமைப்பின் சட்டப்பிரிவு 15 மதம், இனம், சாதி, பாலினம் அல்லது பிறந்த இடம் ஆகிய காரணங்களின் அடிப்படையில் பாகுபாட்டை தடை செய்கிறது. இருப்பினும் மாநிலம் யாருக்காக சிறப்பு விதிகளைக் காக்கலாம்?', 'Women and children only', 'பெண்கள் மற்றும் குழந்தைகள் மட்டுமே', 'Women, children, and socially/educationally backward classes', 'பெண்கள், குழந்தைகள் மற்றும் சமூக/கல்வி ரீதியாக பிற்படுத்தப்பட்ட வர்க்கங்கள்', 'Scheduled Castes and Scheduled Tribes only', 'தாழ்த்தப்பட்ட சாதியினர் மற்றும் பழங்குடியினர் மட்டுமே', 'All minority communities', 'அனைத்து சிறுபான்மை சமூகங்களும்', 'B', NULL, NULL, NULL, NULL, 'MEDIUM');
INSERT INTO questions (topic, subject, category, question_en, question_ta, option_a_en, option_a_ta, option_b_en, option_b_ta, option_c_en, option_c_ta, option_d_en, option_d_ta, correct_answer, explanation_en, explanation_ta, tnpsc_tip_en, tnpsc_tip_ta, difficulty) VALUES ('President', 'Polity', 'Polity', 'The National Emergency proclaimed in 1975 by President Fakhruddin Ali Ahmed was done on whose written advice?', '1975 இல் குடியரசுத் தலைவர் ஃபக்ருதீன் அலி அஹ்மது பிரகடனப்படுத்திய தேசிய அவசரநிலை யாரது எழுத்துப்பூர்வ ஆலோசனையின் பேரில் செய்யப்பட்டது?', 'President''s own initiative', 'குடியரசுத் தலைவரின் சொந்த முன்முயற்சி', 'Cabinet headed by Prime Minister', 'பிரதமர் தலைமையிலான அமைச்சரவை', 'Parliament''s recommendation', 'நாடாளுமன்றத்தின் பரிந்துரை', 'Supreme Court''s direction', 'உச்சநீதிமன்றத்தின் வழிகாட்டுதல்', 'B', NULL, NULL, NULL, NULL, 'MEDIUM');
INSERT INTO questions (topic, subject, category, question_en, question_ta, option_a_en, option_a_ta, option_b_en, option_b_ta, option_c_en, option_c_ta, option_d_en, option_d_ta, correct_answer, explanation_en, explanation_ta, tnpsc_tip_en, tnpsc_tip_ta, difficulty) VALUES ('Constitutional Amendments', 'Polity', 'Polity', 'How many types of majority are prescribed for amending different provisions of the Indian Constitution?', 'இந்திய அரசியலமைப்பின் வெவ்வேறு விதிகளை திருத்துவதற்கு எத்தனை வகையான பெரும்பான்மை நிர்ணயிக்கப்பட்டுள்ளது?', 'Two', 'இரண்டு', 'Three', 'மூன்று', 'Four', 'நான்கு', 'Five', 'ஐந்து', 'B', NULL, NULL, NULL, NULL, 'MEDIUM');
INSERT INTO questions (topic, subject, category, question_en, question_ta, option_a_en, option_a_ta, option_b_en, option_b_ta, option_c_en, option_c_ta, option_d_en, option_d_ta, correct_answer, explanation_en, explanation_ta, tnpsc_tip_en, tnpsc_tip_ta, difficulty) VALUES ('Judiciary', 'Polity', 'Polity', 'The Supreme Court of India has the power of ''Special Leave to Appeal'' under which Article?', 'இந்தியாவின் உச்சநீதிமன்றம் எந்த சட்டப்பிரிவின் கீழ் ''சிறப்பு மேல்முறையீட்டு அனுமதி'' அதிகாரத்தை கொண்டுள்ளது?', 'Article 132', 'சட்டப்பிரிவு 132', 'Article 134', 'சட்டப்பிரிவு 134', 'Article 136', 'சட்டப்பிரிவு 136', 'Article 139', 'சட்டப்பிரிவு 139', 'C', NULL, NULL, NULL, NULL, 'MEDIUM');
